package com.memcyco.scheduler.controller;

/** Custom request headers. */
public final class ApiHeaders {

    /** Random id generated by each browser tab; identifies the editor for edit locks. */
    public static final String EDITOR_ID = "X-Editor-Id";
    /** Token returned when acquiring the edit lock; required to save, renew and release. */
    public static final String EDIT_LOCK_TOKEN = "X-Edit-Lock-Token";

    private ApiHeaders() {
    }
}
